import { readFileSync } from 'fs';
import { join } from 'path';

import MiniSearch from 'minisearch';

// Generated by scripts/generate-search-index.mjs (runs before `dev` and `build`)
export const pages = JSON.parse(
  readFileSync(join(process.cwd(), '.generated/search-index.json'), 'utf8'),
);

function getSearchIndex() {
  const searchClient = new MiniSearch({
    fields: ['title', 'tags', 'summary', 'headings', 'content'], // fields to index for full-text search
    storeFields: [
      'category',
      'date',
      'path',
      'readingTime',
      'slug',
      'summary',
      'tags',
      'title',
    ], // fields to return with search results
    extractField: (doc, field) =>
      field === 'headings' ? doc.headings.map((h) => h.text).join(' ') : doc[field],
    searchOptions: {
      // Set weights of the fields in our data
      boost: { tags: 3, title: 2, headings: 1.5, summary: 1, content: 0.5 },
      // Prefix search (ie. "moto" will match "motorcycle")
      prefix: true,
      // Higher number means terms can be less accurate
      fuzzy: 0.25,
    },
  });

  searchClient.addAll(pages);

  return searchClient;
}

const SearchIndex = getSearchIndex();

export default SearchIndex;
